const { withAppBuildGradle } = require('expo/config-plugins');

/**
 * Signs release builds with the key of whoever is doing the sideloading.
 *
 * `apps/mobile/android/` is generated by `expo prebuild` and git-ignored, so an edit made by hand to
 * `app/build.gradle` survives exactly until the next `--clean`. A config plugin runs on every
 * prebuild instead, which is the only way a signing config is still there tomorrow. Left alone, the
 * React Native template points the release build type at `signingConfigs.debug` — that is what its
 * "Caution! In production…" comment is about — and the APK you hand round ends up carrying
 * `CN=Android Debug`, a key whose password is published in the docs and identical on every machine.
 *
 * The keystore and its passwords never enter the checkout (`.gitignore` refuses `*.keystore` and
 * friends). They go in `~/.gradle/gradle.properties`, which is outside every clone:
 *
 *   SALDO_UPLOAD_STORE_FILE=/Users/you/keys/saldo-release.keystore
 *   SALDO_UPLOAD_STORE_PASSWORD=…
 *   SALDO_UPLOAD_KEY_ALIAS=saldo
 *   SALDO_UPLOAD_KEY_PASSWORD=…
 *
 * The keystore itself comes from (spec §15, step 3):
 *
 *   keytool -genkeypair -v -storetype PKCS12 -keystore saldo-release.keystore \
 *     -alias saldo -keyalg RSA -keysize 2048 -validity 10000
 *
 * Keep it and its passwords backed up: Android identifies an app by its signing key, so losing it
 * means every phone that already has Saldo must uninstall before it can take an update.
 *
 * **A machine without those four properties still builds.** Both the config's contents and the
 * assignment below are guarded by the same `hasProperty` check, so such a machine is left on
 * `signingConfigs.debug` and gets the stock React Native behaviour — `assembleRelease` succeeds and
 * produces a debug-signed `app-release.apk`. Setting `signingConfigs.release` unconditionally does
 * not work: an empty signing config passes Gradle's configuration phase and then fails at
 * packaging with `SigningConfig "release" is missing required property "storeFile"`, which would
 * mean CI and any contributor without a keystore could not run `assembleRelease` at all.
 *
 * Falling back is not silent — Gradle prints a warning naming the missing properties, because a
 * debug-signed release APK is exactly what this plugin exists to stop you handing to someone.
 * `docs/building-android.md` shows how to confirm with `apksigner` which key actually signed it.
 */

const SIGNING_CONFIG = `
        release {
            // Absent on any machine that has no keystore, which is most of them.
            if (project.hasProperty('SALDO_UPLOAD_STORE_FILE')) {
                storeFile file(SALDO_UPLOAD_STORE_FILE)
                storePassword SALDO_UPLOAD_STORE_PASSWORD
                keyAlias SALDO_UPLOAD_KEY_ALIAS
                keyPassword SALDO_UPLOAD_KEY_PASSWORD
            } else {
                project.logger.warn('Saldo: no SALDO_UPLOAD_STORE_FILE property, so this release ' +
                    'build is signed with the shared Android debug key. It is fine for testing and ' +
                    'must not be given to anyone. See docs/building-android.md.')
            }
        }`;

/**
 * Guarded on the same property as the config's contents. An empty `signingConfigs.release` is only
 * rejected when Gradle gets to packaging, so assigning it unconditionally breaks `assembleRelease`
 * on every machine that has no keystore.
 */
const RELEASE_SIGNING_CONFIG_EXPRESSION =
  "project.hasProperty('SALDO_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug";

/**
 * The template declares `signingConfigs.debug` first, so this appends ours after the opening brace.
 */
const SIGNING_CONFIGS_BLOCK = /signingConfigs \{/;

/**
 * Both build types say `signingConfig signingConfigs.debug`, and only the release one may change.
 * The pattern is ordered rather than clever: it starts at `buildTypes {`, walks to the first
 * `release {` inside it, and only then looks for the assignment. The debug build type is declared
 * above `release {`, so it is already behind the cursor and cannot match.
 */
const RELEASE_SIGNING_CONFIG =
  /(buildTypes \{[\s\S]*?release \{[\s\S]*?signingConfig )signingConfigs\.debug/;

/**
 * Rewrites once and complains loudly if the template moved under us. A silent miss here is the bad
 * case: prebuild would succeed and the release APK would quietly go out signed with the debug key.
 */
function replaceOrThrow(contents, pattern, replacement, what) {
  const next = contents.replace(pattern, replacement);
  if (next === contents) {
    throw new Error(
      `withReleaseSigning: could not find ${what} in the generated android/app/build.gradle. ` +
        'The React Native template has probably changed; update the plugin to match it.',
    );
  }
  return next;
}

function withReleaseSigning(config) {
  return withAppBuildGradle(config, (gradleConfig) => {
    let contents = gradleConfig.modResults.contents;

    // A prebuild without `--clean` re-runs the mods over a file we already edited. Bail out so the
    // block is not appended a second time.
    if (contents.includes('SALDO_UPLOAD_STORE_FILE')) {
      return gradleConfig;
    }

    contents = replaceOrThrow(
      contents,
      SIGNING_CONFIGS_BLOCK,
      `signingConfigs {${SIGNING_CONFIG}`,
      'the `signingConfigs` block',
    );
    contents = replaceOrThrow(
      contents,
      RELEASE_SIGNING_CONFIG,
      `$1${RELEASE_SIGNING_CONFIG_EXPRESSION}`,
      "the release build type's `signingConfig`",
    );

    gradleConfig.modResults.contents = contents;
    return gradleConfig;
  });
}

module.exports = withReleaseSigning;
